	public void AnchoredOptionPreservesCompileDiagnosticsAndOriginalOffsets( string hex, int mode, int nativeCode, int nativeOffset, string code, int offset ) {
		var source = Convert.FromHexString( hex );
		var native = Assert.Throws<PcrePatternException>( () => Reference( source, mode, true ) );
		Assert.Equal( nativeCode, (int)native.ErrorCode );
		Assert.EndsWith( $" at offset {nativeOffset}.", native.Message );
		var actual = PcreByteCompiler.Compile( source, Options( mode, true ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( Enum.Parse<PcreByteDiagnosticCode>( code ), actual.Diagnostic?.Code );
		Assert.Equal( offset, actual.Diagnostic?.ByteOffset );
	}

	[Theory]
	[InlineData( "A", "41", 0, 0, "0:1", "" )]
	[InlineData( "(A)\\1", "4141", 0, 0, "0:2,0:1", "" )]
	[InlineData( "A(?R)?B", "41414242", 1, 0, "0:4", "" )]
	[InlineData( "A\\KB", "4142", 1, 0, "1:1", "" )]
	[InlineData( "A.B", "412E42", 17, 0, "0:3", "" )]
	[InlineData( "I", "C4B1", 4105, 0, "0:2", "" )]
	[InlineData( "A", "204120", 65, 1, "1:1", "" )]
	[InlineData( "A", "410D0A", 385, 0, "0:1", "" )]
	public void FirstSuccessfulAttemptSharesVmWorkLimitsAndCancellation( string pattern, string hex, int mode, int offset, string spans, string mark ) {
		var source = Encoding.UTF8.GetBytes( pattern );
		var subject = Convert.FromHexString( hex );
		var reference = Reference( source, mode, true );
		AssertNative( reference, subject, offset, spans, mark );
		AssertNative( Reference( source, mode, false ), subject, offset, spans, mark );
		var steps = new List<int>();
		var ordinarySteps = new List<int>();
		Compare( reference, subject, offset, Compile( source, Options( mode, true ) with { WorkObserver = steps.Add } ).Match( subject, offset ), pattern );
		Compare( reference, subject, offset, Compile( source, Options( mode, false ) with { WorkObserver = ordinarySteps.Add } ).Match( subject, offset ), pattern );
		Assert.Equal( ordinarySteps, steps );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Assert.True( steps.Count > 2 );
		var exact = Compile( source, Options( mode, true ) with { MatchWorkLimit = steps.Count } ).Match( subject, offset );
		Compare( reference, subject, offset, exact, "exact work" );
		var limited = Compile( source, Options( mode, true ) with { MatchWorkLimit = steps.Count - 1 } ).Match( subject, offset );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		using var cancellation = new CancellationTokenSource();
		var cancellable = Compile( source, Options( mode, true ) with {
			WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } }
		} );
		Assert.Throws<OperationCanceledException>( () => cancellable.Match( subject, offset, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( source, Options( mode, true ) with { MatchWorkLimit = 0 }, cancellation.Token ) );
		var invalid = PcreByteCompiler.Compile( new byte[] { 0xFF }, Options( mode, true ) with { MatchWorkLimit = 0 } );
		Assert.Equal( PcreByteDiagnosticCode.InvalidWorkLimit, invalid.Diagnostic?.Code );
	}

	[Theory]
	[InlineData( false )]
	[InlineData( true )]
	public void FailedByteCandidateDoesNotSpendWorkOnTheRemainingSubject( bool observed ) {
		var subject = Encoding.ASCII.GetBytes( new string( 'B', 20000 ) );
		AssertNative( Reference( "A"u8.ToArray(), 0, true ), subject, 0, "", "" );
		var steps = new List<int>();
		var options = Options( 0, true ) with { MatchWorkLimit = 3, WorkObserver = observed ? steps.Add : null };
		var actual = Compile( "A"u8.ToArray(), options ).Match( subject );
		Assert.True( actual.IsSuccess, actual.Diagnostic?.Message );
		Assert.Null( actual.Match );
		if ( observed ) { Assert.Equal( new[] { 1, 2, 3 }, steps ); }
		var limited = Compile( "A"u8.ToArray(), options with { MatchWorkLimit = 2 } ).Match( subject );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
	}

	[Fact]
	public void CompiledCandidatePolicyAndOwnedLabelsSurviveCallerMutation() {
		var source = "(*MARK:N)(A)"u8.ToArray();
		var reference = Reference( source, 0, true );
		AssertNative( reference, "AB"u8.ToArray(), 0, "0:1,0:1", "4E" );
		AssertNative( reference, "BA"u8.ToArray(), 0, "", "" );
		var options = Options( 0, true );
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "Anchored" )?.SetValue( options, false );
		Compare( reference, "AB"u8.ToArray(), 0, compiled.Match( "AB"u8.ToArray() ), "owned source and label" );
		Compare( reference, "BA"u8.ToArray(), 0, compiled.Match( "BA"u8.ToArray() ), "owned candidate policy" );
	}

