	[InlineData( 1 )]
	[InlineData( 9 )]
	[InlineData( 17 )]
	public void SubjectAndOffsetValidationStillPrecedesCandidateFailure( int mode ) {
		var source = "A"u8.ToArray();
		var reference = Reference( source, mode, true );
		AssertNative( reference, "éA"u8.ToArray(), 2, "2:1", "" );
		var compiled = Compile( source, Options( mode, true ) );
		foreach ( var hex in new[] { "FF42", "42FF" } ) {
			var actual = compiled.Match( Convert.FromHexString( hex ) );
			Assert.Null( actual.Match );
			Assert.Equal( PcreByteDiagnosticCode.InvalidUtf8Subject, actual.Diagnostic?.Code );
			Assert.Equal( hex == "FF42" ? 0 : 1, actual.Diagnostic?.ByteOffset );
		}
		var split = compiled.Match( "éA"u8.ToArray(), 1 );
		Assert.Null( split.Match );
		Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, split.Diagnostic?.Code );
		foreach ( var offset in new[] { -1, 4 } ) {
			var outside = compiled.Match( new byte[] { 0xFF }, offset );
			Assert.Null( outside.Match );
			Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, outside.Diagnostic?.Code );
		}
	}

