	public void AnchoringDoesNotConsumeCaptureDepthOrInstructionCapacity( int selection ) {
		var pattern = selection switch {
			0 => new string( 'A', 4095 ),
			1 => String.Concat( String.Concat( Enumerable.Repeat( "()", 256 ) ), "A" ),
			_ => String.Concat( String.Concat( Enumerable.Repeat( "(?:", 256 ) ), "A", new string( ')', 256 ) )
		};
		var mode = selection == 0 ? 16 : 1;
		var source = Encoding.UTF8.GetBytes( pattern );
		var subject = selection == 0 ? Encoding.ASCII.GetBytes( String.Concat( pattern, "B" ) ) : "A"u8.ToArray();
		var spans = selection == 0 ? "0:4095" : selection == 1 ? String.Concat( "0:1,", String.Join( ",", Enumerable.Repeat( "0:0", 256 ) ) ) : "0:1";
		var reference = Reference( source, mode, true );
		AssertNative( reference, subject, 0, spans, "" );
		Compare( reference, subject, 0, Compile( source, Options( mode, true ) ).Match( subject ), "shared capacity" );
	}

